from playwright.sync_api import sync_playwright,expect
from play_qa_support import AppServer,Report,browser,timed_page,advance,snapshot,upgrade_and_offline,enable_survival,enter_lab,run_mission
server=AppServer();report=Report('v2-exploration-qa')
with sync_playwright() as p:
 b=browser(p);c,pg=timed_page(b,server,report);enter_lab(pg);expect(pg.locator('[data-mission=observe]')).to_be_disabled();pg.locator('#labHome').click();enable_survival(pg);pg.evaluate('Math.random=()=>.99');enter_lab(pg);expect(pg.locator('#missionRoute')).to_have_text('푸른 성운 회랑');pg.locator('#missionImage').evaluate('im=>im.decode()');assert '/06_' in pg.locator('#missionImage').get_attribute('src');report.passed('healing guards, existing route, printed cost/risk/rewards and on-demand observatory scene')
 pg.locator('#labPause').click();before=snapshot(pg);pg.locator('[data-mission=observe]').click();assert snapshot(pg)['resources']['amounts']['power']==before['resources']['amounts']['power']-2;advance(pg,15);assert snapshot(pg)['exploration']['active']['remaining']==8;pg.locator('#labPause').click();advance(pg,10);assert snapshot(pg)['research']['points']==3
 run_mission(pg,'observe');pg.locator('#researchDetails>summary').click();expect(pg.locator('#researchImage')).to_have_attribute('src','assets/concepts/v2/08_research_recycling_module.webp');pg.locator('#researchImage').evaluate('im=>im.decode()');expect(pg.locator('[data-research=habitat]')).to_be_disabled();pg.locator('[data-research=scanner]').click();run_mission(pg,'drone');assert '/05_' in pg.locator('#missionImage').get_attribute('src');pg.locator('[data-research=habitat]').click();assert snapshot(pg)['research']['unlocked']==['scanner','habitat'];report.passed('real observation and drone missions, pause/resume, materials/points, prerequisite locks and two paid research unlocks')
 pg.locator('[data-mission=sample]').click();pg.locator('#missionWithdraw').click();s=snapshot(pg);assert s['exploration']['history'][0]['status']=='withdrawn';points=s['research']['points'];advance(pg,20);assert snapshot(pg)['research']['points']==points
 pg.evaluate('Math.random=()=>0');run_mission(pg,'sample');assert snapshot(pg)['exploration']['history'][0]['status']=='failed';assert snapshot(pg)['research']['points']==points;pg.locator('[data-panel=home]').click();enter_lab(pg);assert snapshot(pg)['research']['points']==points;report.passed('voluntary withdrawal, deterministic failed run and view re-entry never create duplicate rewards')
 assert pg.evaluate('document.documentElement.scrollWidth<=innerWidth');pg.locator('#explorationPanel').screenshot(path=str(report.out/'desktop-lab.png'));c.close()
 for w,h in [(768,1024),(390,844)]:
  c,m=timed_page(b,server,report,w,h);enable_survival(m);m.evaluate('Math.random=()=>.99');enter_lab(m);run_mission(m,'observe');assert snapshot(m)['research']['points']==3;assert m.evaluate('document.documentElement.scrollWidth<=innerWidth');m.locator('#explorationPanel').screenshot(path=str(report.out/f'lab-{w}.png'));c.close()
 report.passed('tablet/mobile actual mission completion and responsive scene/cards (emulated)')
 c,o=upgrade_and_offline(b,server,report);enable_survival(o);enter_lab(o);o.locator('[data-mission=observe]').click();expect(o.locator('#missionStatus')).to_contain_text('수동 전파 관측');o.locator('#missionWithdraw').click();c.close();report.passed('mission/research model initializes after offline restart; controls work even without optional art')
 b.close()
report.finish();server.close()
